// Actual Bun bundles frozen from386d3f8ca2725be176619baf8449d76febbc976d before D6 edits.
// First-party v2 endpoints, stored compressed to retain a portable immutable cross-version fixture.
import { gunzipSync } from "node:zlib";
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { join } from "node:path";
const fixtures = {"client": {"sha256": "4b621ecb43356f97968639294dd3f31208b4a433d986b3c3d2302738f5f8b162", "gzip": ""}, "server": {"sha256": "01a4e90eb64720a5c76b1c82b8f5ce890761a2a5d9c7a24a5e27ccc7a4507dfa", "gzip": ""}};
export async function frozenV2(root:string):Promise<{client:any;server:any}> {
 const modules:any={};
 for(const name of ["client","server"] as const) {
  const bytes=gunzipSync(Buffer.from(fixtures[name].gzip,"base64"));
  if(createHash("sha256").update(bytes).digest("hex")!==fixtures[name].sha256) throw new Error("Frozen v2 fixture integrity failed");
  const path=join(root,`frozen-v2-${name}.mjs`);
  // Native modules cannot be inlined into an immutable JS fixture; resolve the unchanged installed dependency.
  writeFileSync(path,bytes.toString("utf8").replaceAll('"koffi"',JSON.stringify(createRequire(import.meta.resolve("@archcontext/core")).resolve("koffi"))));
  modules[name]=await import(path);
 }
 return modules;
}
